/bin/zsh -lc "python3 -c 'import json,itertools
x=json.load(open(\"input.json\"))
def reachable(s,t,removed):
 seen={s}; todo=[s]
 while todo:
  a=todo.pop()
  for e in x[\"edges\"]:
   if e[\"id\"] not in removed and e[\"source\"]==a and e[\"target\"] not in seen:
    seen.add(e[\"target\"]); todo.append(e[\"target\"])
 return t in seen
es=sorted([e for e in x[\"edges\"] if e[\"removable\"]],key=lambda e:e[\"id\"])
best=None; valid=0
for bits in itertools.product((False,True),repeat=len(es)):
 removed=[e[\"id\"] for e,b in zip(es,bits) if b]
 if any(reachable(s,t,removed) for s,t in x[\"forbidden\"]): continue
 if not all(reachable(s,t,removed) for s,t in x[\"required\"]): continue
 valid+=1
 objective=(sum(e[\"cost\"] for e,b in zip(es,bits) if b),len(removed),removed)
 if best is None or objective<best: best=objective
rp=[]; ap=[]
for p in x[\"probes\"]:
 if reachable(p[\"source\"],p[\"target\"],[]):
  rp.append(p[\"id\"])
  if p[\"signed\"] is True and p[\"audience\"]==\"control\" and p[\"tenant\"]==p[\"resource_tenant\"] and x[\"now\"]<p[\"expires\"] and p[\"key\"] not in x[\"revoked_keys\"]: ap.append(p[\"id\"])
print(json.dumps(dict(reachable_probes=sorted(rp),authorized_probes=sorted(ap),repair_edges=best[2],repair_cost=best[0])))
print(\"subsets_checked\",2**len(es),\"feasible_subsets\",valid)'"

